            error = resolve_symbol (mod, reloc_symtab, &sym, shndx);
            if (error != DWFL_E_NOERROR
                && !(error == DWFL_E_RELUNDEF && shndx == SHN_COMMON))
              return error;
          }

        value = sym.st_value;
      }

